/**
 * OAppShell v3.0
 *
 * P0-2 修复: 零 inline style — grid 布局全在 oui.css
 * P0-3 修复: 移动端用 <dialog> — 零 JS matchMedia,零 SSR 闪烁
 * P1-4 修复: <dialog> 原生 focus trap / Esc 关闭 / top-layer
 *
 * 布局原理:
 *   • CSS-only 响应式: .oui-app-shell + .oui-sidebar-col 用 CSS media query
 *   • 移动端 sidebar: <dialog class="oui-sidebar-dialog"> — showModal() / close()
 *   • grid-template-columns 在 CSS 里定义,JS 只控制 data-sidebar-collapsed
 */
'use client';

import { forwardRef, useRef, useEffect, type ReactNode } from 'react';
import { OTopBar } from './OTopBar';
import { OSideBar, type SideBarNavItem } from './OSideBar';

export interface OAppShellProps {
  children: ReactNode;
  topbar?: ReactNode | false;
  sidebar?: ReactNode | false;
  footer?: ReactNode;
  topbarProps?: {
    logo?: ReactNode;
    centerSlot?: ReactNode;
    actionsSlot?: ReactNode;
    title?: string;
  };
  sidebarProps?: {
    items: SideBarNavItem[];
    activeId?: string;
    onItemClick?: (item: SideBarNavItem) => void;
    topSlot?: ReactNode;
    bottomSlot?: ReactNode;
  };
  sidebarCollapsed?: boolean;
  onSidebarCollapsedChange?: (collapsed: boolean) => void;
  /** 完全隐藏 sidebar(宽度=0,不占 grid 空间) */
  sidebarHidden?: boolean;
  onSidebarHiddenChange?: (hidden: boolean) => void;
  className?: string;
}

export const OAppShell = forwardRef<HTMLDivElement, OAppShellProps>(
  function OAppShell(
    {
      children,
      topbar,
      sidebar,
      footer,
      topbarProps,
      sidebarProps,
      sidebarCollapsed: collapsed,
      onSidebarCollapsedChange,
      sidebarHidden: hidden,
      onSidebarHiddenChange,
      className,
    },
    ref
  ) {
    const dialogRef = useRef<HTMLDialogElement>(null);

    const showTopbar  = topbar !== false;
    const showSidebar = sidebar !== false && (!!sidebarProps || (sidebar !== undefined));

    // 移动端 dialog 开关
    const openMobileMenu  = () => dialogRef.current?.showModal?.();
    const closeMobileMenu = () => dialogRef.current?.close?.();

    // dialog 点击 backdrop 关闭
    useEffect(() => {
      const dialog = dialogRef.current;
      if (!dialog) return;
      const onClick = (e: MouseEvent) => {
        const rect = dialog.getBoundingClientRect();
        if (
          e.clientX < rect.left || e.clientX > rect.right ||
          e.clientY < rect.top  || e.clientY > rect.bottom
        ) dialog.close();
      };
      dialog.addEventListener('click', onClick);
      return () => dialog.removeEventListener('click', onClick);
    }, []);

    const sidebarNode =
      sidebar !== false && sidebar !== undefined ? sidebar
      : sidebarProps
        ? <OSideBar
            {...sidebarProps}
            collapsed={collapsed}
            hidden={hidden}
            onCollapsedChange={onSidebarCollapsedChange}
            onHiddenChange={onSidebarHiddenChange}
            onItemClick={(item) => {
              sidebarProps.onItemClick?.(item);
              closeMobileMenu(); // 移动端点击导航项自动关 dialog
            }}
          />
        : null;

    const topbarNode =
      topbar === false ? null
      : topbar !== undefined ? topbar
      : <OTopBar
          {...topbarProps}
          showMenuButton={showSidebar}
          onMenuToggle={openMobileMenu}   // 移动端点汉堡打开 dialog
        />;

    return (
      <div
        ref={ref}
        className={['oui-app-shell', className ?? ''].join(' ')}
        data-sidebar-collapsed={collapsed ? 'true' : undefined}
        data-sidebar-hidden={hidden ? 'true' : undefined}
        data-no-topbar={!showTopbar ? 'true' : undefined}
      >
        {/* Topbar — 跨全宽 */}
        {showTopbar && (
          <div className="oui-topbar-row">{topbarNode}</div>
        )}

        {/* Desktop sidebar — CSS grid col 1 */}
        {showSidebar && (
          <div className="oui-sidebar-col">{sidebarNode}</div>
        )}

        {/* Main content — container query 启用 */}
        <main className="oui-main">
          {children}
          {footer && <footer>{footer}</footer>}
        </main>

        {/* Mobile sidebar — 原生 <dialog> */}
        {showSidebar && (
          <dialog
            ref={dialogRef}
            className="oui-sidebar-dialog"
            aria-label="Navigation"
          >
            {sidebarNode}
          </dialog>
        )}
      </div>
    );
  }
);

OAppShell.displayName = 'OAppShell';
