/**
 * OTopBar v3.0
 * 零 inline style — 全部 class,伪类在 oui.css 处理。
 */
import { forwardRef, type ReactNode } from 'react';

export interface OTopBarProps {
  logo?: ReactNode;
  centerSlot?: ReactNode;
  actionsSlot?: ReactNode;
  title?: string;
  showMenuButton?: boolean;
  onMenuToggle?: () => void;
  className?: string;
}

export const OTopBar = forwardRef<HTMLElement, OTopBarProps>(function OTopBar(
  { logo, centerSlot, actionsSlot, title, showMenuButton, onMenuToggle, className },
  ref
) {
  return (
    <header
      ref={ref}
      className={['oui-topbar', className ?? ''].join(' ')}
      role="banner"
    >
      <div className="oui-topbar__left">
        {showMenuButton && (
          <button
            type="button"
            className="oui-menu-btn"
            onClick={onMenuToggle}
            aria-label="Toggle menu"
            aria-expanded={undefined}
          >
            <span className="oui-menu-btn__bar" />
            <span className="oui-menu-btn__bar" />
            <span className="oui-menu-btn__bar" />
          </button>
        )}
        {logo ?? (
          <span className="oui-topbar__title">{title ?? 'Helios'}</span>
        )}
      </div>

      <div className="oui-topbar__center">{centerSlot}</div>

      <div className="oui-topbar__right">{actionsSlot}</div>
    </header>
  );
});

OTopBar.displayName = 'OTopBar';
